  function profilePlaceholder(){return `<article class="gr-personal-placeholder" data-gr-profile-placeholder><header>${photo('avatarOfficial','盖世游戏官方','gr-placeholder-avatar')}<div><strong>盖世游戏官方 <i>官方</i></strong><small>回复于37分钟前</small></div><span aria-hidden="true">···</span></header><h2><em>置顶</em>盖世游戏共创计划 · 第一期｜下一步做什么，你来提建议</h2><p>各位玩家，大家好！盖世游戏共创计划第一期来了！我们想邀请你一起参与产品改进，让后续更新更贴近你的游戏体验和实际需要。</p><div class="gr-placeholder-topics"><span>#共创计划</span><span>#GameHub</span><span>#意见征集</span></div>${photo('postCover','盖世游戏共创计划','gr-placeholder-cover')}</article>`;}
